```

```sql
SELECT Policy.Policy_Identifier, SUM(CASE WHEN Agent.Agent_Id IS NOT NULL THEN 1 ELSE 0 END) AS "agent_sold", SUM(CASE WHEN Agent.Agent_Id IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS "percentage_sold" FROM Policy, Agreement_Assessment AS Agent WHERE Policy.Policy_Number = Agent.Policy_Number GROUP BY Policy.Policy_Identifier;
```

```sql
SELECT Policy.Policy_Identifier, SUM(CASE WHEN Agent.Agent_Id IS NOT NULL THEN 1 ELSE 0 END) AS "agent_sold", SUM(CASE WHEN Agent.Agent_Id IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS "percentage_sold" FROM Policy, Agreement_Assessment WHERE Policy.Policy_Number = Agreement_Assessment.Policy_Number GROUP BY Policy.Policy_Identifier;
```

```sql
SELECT T1.Policy_Holder, T2.Claim_Offer_Identifier, T3.Claim_Amount FROM Policy_Coverage_Detail AS T1 JOIN Claim AS T2 ON T1.Claim_Identifier = T2.Claim_Identifier JOIN Claim_Amount AS T3 ON T1.Claim_Amount_Identifier = T3.Claim_Amount_Identifier;
```

```sql
SELECT c.claim_identifier, p.policy_number, p.policy_holder, pm.policy_amount, cat.catastrophe_name, ag.agent_name, cp.claim_offer_identifier, cp.amount_type_code, cp.event_date, cp.claim_amount, lp.claim_amount_identifier, lr.claim_amount_identifier, ep.claim_amount_identifier, er.claim_amount_identifier FROM claim c JOIN policy_coverage_detail cpd ON c.claim_identifier = cpd.policy_identifier JOIN policy p ON cpd.policy_identifier = p.policy_identifier JOIN catastrophe cat ON c.catastrophe_identifier = cat.catastrophe_identifier JOIN agreement_party_role agpr ON p.policy_identifier = agpr.party_identifier JOIN agent ag ON agpr.party_identifier = ag.agent_identifier JOIN claim_payment cp ON c.claim_identifier = cp.claim_identifier LEFT JOIN loss_payment lp ON cp.claim_offer_identifier = lp.claim_offer_identifier LEFT JOIN loss_reserve lr ON cp.claim_offer_identifier = lr.claim_offer_identifier LEFT JOIN expense_payment ep ON cp.claim_offer_identifier = ep.claim_offer_identifier LEFT JOIN expense_reserve er ON cp.claim_offer_identifier = er.claim_amount_identifier;
```

```sql
SELECT p.policy_number, a.agent_id FROM policy p JOIN agreement a ON p.policy_identifier = a.agreement_identifier;
```

```sql
SELECT p.policy_number, a.agent_id FROM policy p JOIN agreement a ON p.policy_identifier = a.agreement_identifier;
```

```sql
SELECT p.policy_number, COUNT(c.claim_identifier) AS number_of_claims, SUM(cp.claim_amount) AS total_claim_amount, SUM(l.claim_amount_identifier) AS total_loss_amount, SUM(l.claim_amount_identifier) / NULLIF(p.policy_amount, 0) AS loss_ratio FROM claim c JOIN claim_amount cp ON c.claim_identifier = cp.claim_identifier JOIN policy p ON c.policy_identifier = p.policy_identifier LEFT JOIN loss_payment l ON cp.claim_amount_identifier = l.claim_amount_identifier GROUP BY p.policy_number, p.policy_amount;
```

```sql
SELECT a.agent_name, p.policy_number, c.catastrophe_name FROM Agreement_Assessment a JOIN Policy p ON a.agreement_id = p.policy_agent_id JOIN Claim c ON p.policy_number = c.company_claim_number JOIN Catastrophe cat ON c.catastrophe_identifier = cat.catastrophe_identifier;
```

```sql
SELECT c.claim_identifier, SUM(l.claim_amount) AS total_loss_amount FROM claim c JOIN loss_payment l ON c.claim_identifier = l.claim_amount_identifier GROUP BY c.claim_identifier ORDER BY total_loss_amount DESC NULLS LAST;
```
